@extends('layouts.app') @section('page-title','Support Inbox') @section('content')@forelse($threads as $t)<article class="panel support-thread"><div class="panel-head"><div><span class="kicker">{{ $t->category }}</span><h2>{{ $t->subject }}</h2></div><x-status :value="$t->status"/></div>@foreach($t->messages as $m)<div class="message"><p>{{ $m->message }}</p><small>{{ $m->sender?->full_name ?: 'Hospital user' }} · {{ $m->created_at?->format('d M h:i A') }}</small></div>@endforeach<form method="post" action="{{ route('staff.support.reply',$t) }}">@csrf<div class="form-grid"><label class="span-2">Reply<textarea name="message" rows="3" maxlength="3000" required></textarea></label><label>Status<select name="status">@foreach(['OPEN','IN_PROGRESS','RESOLVED','CLOSED'] as $v)<option @selected($t->status===$v)>{{ $v }}</option>@endforeach</select></label></div><button class="btn btn-primary">Send reply</button></form></article>@empty<x-empty title="No support requests"/>@endforelse{{ $threads->links() }}@endsection